INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l19',4,4,19,'The Stuff of Dreams','梦之物质','whether … or not、although 引导的让步状语从句、过去分词短语作状语(People woken during…, said…)、过去完成进行时(had been dreaming)、what 引导的名词从句(what mattered was…)(NCE4 无 KS 页,考点由课文结构自取;IP:源为克里斯托弗·埃文斯《倾听者》文章,内容为‘睡眠功能·REM快速眼动·做梦’的科学事实,已用 100% 原创行文复述,真实人物 William Dement 已换泛称‘一位精神科医生’,无逐句改写;题材=睡眠与梦的科学·无害;美语化 behavior/color;第四册第19课·第四单元开工)','相当清楚的是,睡眠一定为我们做着什么;而既然我们一生有那么多时间在睡,这个“什么”多半很重要。人们已经就它究竟为何而存在思索了几千年,可有一项古怪的发现始终让这问题悬而不决:睡眠似乎并不单单是让身体休息的一种方式。那种能松弛肌肉的休息,只要安静地躺一会儿、甚至坐一会儿,一样能得到。身体自身的组织无论我们睡不睡都在自我修复、自我更新,而且事实上,它们在多多少少持续活动时状态最好;睡眠中甚至还会有一定量的活动,恰恰是为了不让肌肉变僵。如果睡眠不是为了让身体休息,那也许需要休息的是大脑?这听上去像个貌似合理的假设,却有两个事实挡在前头。第一,大脑的电活动可以通过把小电极贴到头皮上来记录;记录显示,睡眠中那活动的模式虽有变化,总量却并不下降。第二——这一点更有意思——若干年前,一位精神科医生描述了一件怪事:寻常的一夜睡眠里,会被一阵阵突如其来的眼球运动打断,有的缓慢飘移,有的急促跳动。在这样一阵眼动中被唤醒的人,几乎总说自己刚才在做梦;在别的时刻被唤醒,则说什么梦也没有。实验又更进一步。一组志愿者一连数晚,每当眼球开始转动就被打扰;另一组被打扰得同样频繁,却只在安静无眼动的睡眠里被打扰——结果第一组很快开始显出古怪的情绪与性格失调,第二组却几乎毫无影响。其中的含意十分惊人:要紧的并不是睡眠本身的丧失,而是做梦的丧失。','{"q":"Listen and answer — What is going on when a person experiences rapid eye-movements during sleep?","options":["The person is dreaming","The person is waking up","The person is resting the muscles","The person has stopped breathing"],"answer_index":0}'::jsonb,'{"title":"whether…or not / although 让步 / 过去分词作状语 / 过去完成进行时 / what 名词从句","intro":"①whether … or not:‘无论…与否’。②although 引导让步:Although the pattern changes, the total does not fall。③过去分词短语作状语:People woken during that phase said …。④过去完成进行时 had + been + doing:they had been dreaming。⑤what 引导名词从句:What mattered was not the sleep but the dreaming。","table":{"headers":["用法","结构","例子"],"rows":[["whether…or not","whether … or not","whether we sleep or not"],["although 让步","Although + 从句, 主句","Although the pattern changes, …"],["过去分词状语","过去分词短语, 主句","Woken in that phase, they said …"],["过去完成进行","had been + doing","they had been dreaming"],["what 名词从句","What … + 谓语","What mattered was the dreaming"]]},"specialRules":[{"rule":"过去完成进行时 had + been + 现在分词,强调动作在过去某时之前一直进行。","mark":"had been doing"},{"rule":"although 引导让步从句时,主句前不再加 but(汉语‘虽然…但是…’,英语两者只用其一)。","mark":"Although …, 主句(无 but)"},{"rule":"美式拼写:behavior(行为,英式 behaviour)、color(颜色,英式 colour)。本课已按美语写。","mark":"behavior / color"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l19',1,NULL,'It is fairly clear that sleep must do something for us, and since we spend so much of our lives asleep, that something is probably important. There has been speculation for thousands of years about what it is for, yet one odd finding keeps the whole question alive: sleep does not seem to be simply a way of giving the body a rest.','相当清楚的是,睡眠一定为我们做着什么;而既然我们一生有那么多时间在睡,这个“什么”多半很重要。人们已经就它究竟为何而存在思索了几千年,可有一项古怪的发现始终让这问题悬而不决:睡眠似乎并不单单是让身体休息的一种方式。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l19',2,NULL,'The kind of rest that loosens the muscles can be had just as well by lying, or even sitting, quietly for a while. The body''s own tissues repair and renew themselves whether we sleep or not, and in fact they work best when they are kept more or less constantly in motion; a certain amount of movement even goes on during sleep, precisely to stop the muscles from growing stiff.','那种能松弛肌肉的休息,只要安静地躺一会儿、甚至坐一会儿,一样能得到。身体自身的组织无论我们睡不睡都在自我修复、自我更新,而且事实上,它们在多多少少持续活动时状态最好;睡眠中甚至还会有一定量的活动,恰恰是为了不让肌肉变僵。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l19',3,NULL,'If sleep is not there to rest the body, then perhaps it is the brain that needs the rest. This sounds like a plausible hypothesis, but two facts stand in its way. First, the electrical activity of the brain can be traced by fixing small electrodes to the scalp, and the record shows that, although the pattern of that activity changes during sleep, its total amount does not fall.','如果睡眠不是为了让身体休息,那也许需要休息的是大脑?这听上去像个貌似合理的假设,却有两个事实挡在前头。第一,大脑的电活动可以通过把小电极贴到头皮上来记录;记录显示,睡眠中那活动的模式虽有变化,总量却并不下降。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l19',4,NULL,'Second — and this is the more interesting point — a psychiatrist some years ago described a strange thing: the ordinary night''s sleep is punctuated by sudden bursts of eye movement, some of them slow and drifting, others quick and jerky. People woken during one of these bursts nearly always said they had been dreaming; woken at other moments, they reported nothing.','第二——这一点更有意思——若干年前,一位精神科医生描述了一件怪事:寻常的一夜睡眠里,会被一阵阵突如其来的眼球运动打断,有的缓慢飘移,有的急促跳动。在这样一阵眼动中被唤醒的人,几乎总说自己刚才在做梦;在别的时刻被唤醒,则说什么梦也没有。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l19',5,NULL,'When one group of volunteers was disturbed, night after night, every time their eyes began to move, while a second group was disturbed just as often but only during quiet, movement-free sleep, the first group soon began to show odd disorders of mood and personality, and the second seemed hardly affected at all. The implication was striking: what mattered was not the loss of sleep itself, but the loss of dreaming.','一组志愿者一连数晚,每当眼球开始转动就被打扰;另一组被打扰得同样频繁,却只在安静无眼动的睡眠里被打扰——结果第一组很快开始显出古怪的情绪与性格失调,第二组却几乎毫无影响。其中的含意十分惊人:要紧的并不是睡眠本身的丧失,而是做梦的丧失。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
