INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l19','go on','',NULL,'/ɡoʊ ɑːn/','Speculation about sleep has been going on for ages.','关于睡眠的思索已持续了很久。','The noise went on all night.','那噪声响了一整夜。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l19','stand in the way','',NULL,'/stænd ɪn ðə weɪ/','Two facts stand in its way.','有两个事实挡在前头。','Nothing stands in the way of success.','没有什么能阻挡成功。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l19','night after night','',NULL,'/naɪt ˈæftər naɪt/','They were disturbed night after night.','他们一夜又一夜地被打扰。','He worked late night after night.','他夜复一夜地加班到很晚。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l19','not ... but','',NULL,'/nɑːt bʌt/','What mattered was not the sleep but the dreaming.','要紧的不是睡眠,而是做梦。','It was not luck but skill.','那不是运气,而是本事。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp1','choice','{"stem":"\"The body repairs itself ___ we sleep or not.\"(‘无论…与否’,填连词)","options":["whether","that","if only","unless"],"answer_index":0,"stem_cn":"无论我们睡不睡,身体都会自我修复。","explanation_cn":"‘无论…与否’用 whether … or not。✓ repairs itself whether we sleep or not. ✗ that / if only / unless:表‘无论…与否’用 whether。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp1','choice','{"stem":"\"Sleep has a function ___ we understand it or not.\"(‘无论…与否’,填连词)","options":["because","since","whether","though"],"answer_index":2,"stem_cn":"无论我们是否理解,睡眠都有其功能。","explanation_cn":"‘无论…与否’用 whether。✓ has a function whether we understand it or not. ✗ though / since / because:表‘无论…与否’用 whether。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp1','choice','{"stem":"\"They dreamed ___ or not they remembered it.\"(‘无论…与否’,与 or not 呼应的连词)","options":["if","that","unless","whether"],"answer_index":3,"stem_cn":"无论他们记不记得,他们都做了梦。","explanation_cn":"whether … or not,‘无论…与否’。✓ dreamed whether or not they remembered it. ✗ that / if / unless:此结构用 whether。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp2','choice','{"stem":"\"___ the pattern changes, the total activity does not fall.\"(‘尽管’,填让步连词)","options":["Once","Because","Although","Unless"],"answer_index":2,"stem_cn":"尽管活动的模式变了,总量却没减少。","explanation_cn":"‘尽管’引导让步,用 Although。✓ Although the pattern changes, the total does not fall. ✗ Because / Once / Unless:表让步用 Although。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp2','choice','{"stem":"\"The brain stays busy ___ the body lies still.\"(‘尽管、虽然’,填连词)","options":["because","once","whether","although"],"answer_index":3,"stem_cn":"尽管身体躺着不动,大脑却依旧忙碌。","explanation_cn":"‘尽管、虽然’引导让步,用 although。✓ stays busy although the body lies still. ✗ because / once / whether:表让步用 although。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp2','choice','{"stem":"\"___ sleep looks like rest, the brain is far from idle.\"(‘虽然’,填让步连词)","options":["Although","Before","Unless","Since"],"answer_index":0,"stem_cn":"睡眠看着像休息,大脑却远非闲着。","explanation_cn":"‘虽然’引导让步,用 Although。✓ Although sleep looks like rest, the brain is far from idle. ✗ Since / Unless / Before:表让步用 Although。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp3','choice','{"stem":"\"___ during eye-movement sleep, people usually reported dreams.\"(过去分词作状语,‘被唤醒时’;wake 的过去分词)","options":["To wake","Wake","Waking","Woken"],"answer_index":3,"stem_cn":"在眼动睡眠中被唤醒时,人们通常报告做了梦。","explanation_cn":"过去分词短语作状语,表被动‘被唤醒时’;wake 的过去分词 Woken。✓ Woken during eye-movement sleep, people reported dreams. ✗ Waking(主动)/ Wake / To wake:被动状语用过去分词。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp3','choice','{"stem":"\"___ by a sudden noise, the sleeper lost the dream.\"(过去分词作状语,‘被…惊醒’;startle 的过去分词)","options":["Startled","To startle","Startle","Startling"],"answer_index":0,"stem_cn":"被一声突响惊醒,睡者忘了那个梦。","explanation_cn":"过去分词短语作状语,表被动‘被…惊醒’;startle 的过去分词 Startled。✓ Startled by a sudden noise, the sleeper lost the dream. ✗ Startling(主动)/ Startle / To startle:被动状语用过去分词。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp3','choice','{"stem":"\"___ of dreaming for nights, the first group grew disturbed.\"(过去分词作状语,‘被剥夺…’;deprive 的过去分词)","options":["Depriving","Deprive","To deprive","Deprived"],"answer_index":3,"stem_cn":"一连数晚被剥夺做梦后,第一组变得烦乱。","explanation_cn":"过去分词短语作状语,表被动‘被剥夺…’;deprive 的过去分词 Deprived。✓ Deprived of dreaming for nights, the group grew disturbed. ✗ Depriving(主动)/ Deprive / To deprive:被动状语用过去分词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp4','choice','{"stem":"\"People woken in that phase said they ___ been dreaming.\"(过去完成进行时:他们‘一直在做梦’,填第一个助动词)","options":["have","had","has","were"],"answer_index":1,"stem_cn":"在那个阶段被唤醒的人说他们刚才一直在做梦。","explanation_cn":"过去完成进行时 had + been + 现在分词;第一个助动词用 had。✓ they had been dreaming. ✗ have / has / were:过去完成进行用 had been doing。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp4','choice','{"stem":"\"By the time we woke him, he ___ been dreaming for a while.\"(过去完成进行时,填第一个助动词)","options":["had","have","was","has"],"answer_index":0,"stem_cn":"我们叫醒他时,他已经做了好一会儿梦。","explanation_cn":"过去完成进行时 had + been + 现在分词。✓ he had been dreaming for a while. ✗ have / has / was:用 had been doing。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp4','choice','{"stem":"\"She realized she ___ been sleeping deeply until the alarm rang.\"(过去完成进行时,填第一个助动词)","options":["have","has","was","had"],"answer_index":3,"stem_cn":"她意识到闹钟响之前自己一直睡得很沉。","explanation_cn":"过去完成进行时 had + been + 现在分词。✓ she had been sleeping deeply. ✗ have / has / was:用 had been doing。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp5','choice','{"stem":"\"___ mattered was not the sleep but the dreaming.\"(名词从句作主语,‘所…的’)","options":["That","What","Which","Whether"],"answer_index":1,"stem_cn":"要紧的不是睡眠,而是做梦。","explanation_cn":"名词从句作主语,‘所…的’;What=the thing that。✓ What mattered was not the sleep but the dreaming. ✗ That / Which / Whether:此处用 What。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp5','choice','{"stem":"\"Scientists still debate ___ sleep is really for.\"(名词从句作宾语,‘…什么’)","options":["how","which","that","what"],"answer_index":3,"stem_cn":"科学家仍在争论睡眠究竟为了什么。","explanation_cn":"名词从句作宾语,‘…什么’;debate what …。✓ debate what sleep is really for. ✗ that / which / how:此处用 what。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp5','choice','{"stem":"\"___ the brain does during dreams remains a puzzle.\"(名词从句作主语,‘…的事’)","options":["What","Which","Whether","That"],"answer_index":0,"stem_cn":"大脑在做梦时究竟在干什么,仍是个谜。","explanation_cn":"名词从句作主语,‘…的事’。✓ What the brain does during dreams remains a puzzle. ✗ That / Which / Whether:此处用 What。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp6','choice','{"stem":"\"A careful guess offered to explain facts is a ___.\"(“假设、假说”用哪个词)","options":["receipt","promise","hypothesis","order"],"answer_index":2,"stem_cn":"为解释事实而提出的谨慎猜测。","explanation_cn":"为解释事实而提出的谨慎猜测是 hypothesis(假设)。✓ a careful guess is a hypothesis. ✗ promise 承诺;✗ order 命令;✗ receipt 收据——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp6','choice','{"stem":"\"A doctor who treats disorders of the mind is a ___.\"(“精神科医生”用哪个词)","options":["farmer","psychiatrist","dentist","pilot"],"answer_index":1,"stem_cn":"治疗精神/心理疾病的医生。","explanation_cn":"治疗精神/心理疾病的医生是 psychiatrist(精神科医生)。✓ a doctor who treats the mind is a psychiatrist. ✗ dentist 牙医;✗ farmer 农夫;✗ pilot 飞行员——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',5,'am4_l19_gp6','choice','{"stem":"\"Reasonable and likely to be true is being ___.\"(“貌似合理的、可信的”用哪个词)","options":["false","empty","silent","plausible"],"answer_index":3,"stem_cn":"看起来合情合理、可信的。","explanation_cn":"看起来合情合理、可信的是 plausible。✓ reasonable and likely to be true is plausible. ✗ false 假的;✗ silent 沉默的;✗ empty 空的——都相反或不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',6,NULL,'choice','{"stem":"hypothesis 的意思是:","options":["证据","事实","假设,假说","结论"],"answer_index":2,"explanation_cn":"hypothesis = 假设、假说。✓ this sounds like a plausible hypothesis."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',6,NULL,'choice','{"stem":"tissue 的意思是:","options":["皮肤","血液","骨骼","(生物)组织"],"answer_index":3,"explanation_cn":"tissue = (生物)组织。✓ the body''s own tissues repair themselves."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',6,NULL,'choice','{"stem":"plausible 的意思是:","options":["荒谬的","貌似合理的,可信的","沉默的","空的"],"answer_index":1,"explanation_cn":"plausible = 貌似合理的、可信的。✓ a plausible hypothesis."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',6,NULL,'choice','{"stem":"disorder 的意思是:","options":["失调,紊乱","秩序","平静","健康"],"answer_index":0,"explanation_cn":"disorder = 失调、紊乱。✓ odd disorders of mood and personality."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',6,NULL,'choice','{"stem":"jerky 的意思是:","options":["缓慢的","急动的,颠簸的","平稳的","柔软的"],"answer_index":1,"explanation_cn":"jerky = 急动的、颠簸的。✓ others quick and jerky."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',6,NULL,'choice','{"stem":"implication 的意思是:","options":["假期","命令","含意,暗示","礼物"],"answer_index":2,"explanation_cn":"implication = 含意、暗示。✓ the implication was striking."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',7,NULL,'cloze','{"stem":"第 1 空","context":"Sleep must have a function, ___1___ we understand it or not. ___2___ the brain''s pattern changes in sleep, its total activity does not fall. People ___3___ during eye-movement sleep said they had been dreaming. ___4___ mattered was not the sleep but the dreaming.","blank_no":1,"options":["whether","that","if only","unless"],"answer_index":0,"explanation_cn":"‘无论…与否’用 whether。✓ Sleep must have a function, whether we understand it or not."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',7,NULL,'cloze','{"stem":"第 2 空","context":"Sleep must have a function, ___1___ we understand it or not. ___2___ the brain''s pattern changes in sleep, its total activity does not fall. People ___3___ during eye-movement sleep said they had been dreaming. ___4___ mattered was not the sleep but the dreaming.","blank_no":2,"options":["Although","Because","Once","Unless"],"answer_index":0,"explanation_cn":"‘尽管’引导让步,用 Although。✓ Although the pattern changes, its total activity does not fall."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',7,NULL,'cloze','{"stem":"第 3 空","context":"Sleep must have a function, ___1___ we understand it or not. ___2___ the brain''s pattern changes in sleep, its total activity does not fall. People ___3___ during eye-movement sleep said they had been dreaming. ___4___ mattered was not the sleep but the dreaming.","blank_no":3,"options":["woken","waking","wake","to wake"],"answer_index":0,"explanation_cn":"过去分词短语作状语,‘被唤醒的’。✓ People woken during eye-movement sleep said they had been dreaming."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',7,NULL,'cloze','{"stem":"第 4 空","context":"Sleep must have a function, ___1___ we understand it or not. ___2___ the brain''s pattern changes in sleep, its total activity does not fall. People ___3___ during eye-movement sleep said they had been dreaming. ___4___ mattered was not the sleep but the dreaming.","blank_no":4,"options":["What","That","Which","Whether"],"answer_index":0,"explanation_cn":"名词从句作主语,‘所…的’。✓ What mattered was not the sleep but the dreaming."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',8,NULL,'choice','{"stem":"What is going on when a person shows rapid eye-movements during sleep?","options":["The person is in a coma","The person is resting the muscles","The person is dreaming","The person is waking up"],"answer_index":2,"explanation_cn":"录音说当人出现快速眼动时,他正在做梦。✓ dreaming."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',8,NULL,'choice','{"stem":"Why is sleep probably not just a way of resting the body?","options":["Rest is impossible while sitting","The body''s tissues repair themselves whether we sleep or not","The body never moves in sleep","Sleep makes muscles weaker"],"answer_index":1,"explanation_cn":"录音说睡眠多半不只是让身体休息,因为身体组织无论睡不睡都在自我修复。✓ tissues repair whether we sleep or not."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',8,NULL,'choice','{"stem":"What happened to volunteers who were kept from dreaming for several nights?","options":["They stopped needing sleep","They felt completely fine","They slept more deeply","They began to show disorders of mood and personality"],"answer_index":3,"explanation_cn":"录音说一连数晚被剥夺做梦的志愿者,开始出现情绪与性格的失调。✓ disorders of mood and personality."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',9,NULL,'choice','{"stem":"你想说\"无论我们睡不睡,身体都会自我修复\"(whether … or not):","options":["The body repairs itself whether we sleep or not.","The body repairs itself whether we sleep or no.","The body repairs itself if we sleep or not.","The body repairs itself that we sleep or not."],"answer_index":0,"explanation_cn":"whether … or not,‘无论…与否’;不用 that、末尾用 or not(不写 or no)、也不用 if(if 不与 or not 这样并用于陈述)。✓ whether we sleep or not. 场合:说“无论…与否”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',9,NULL,'choice','{"stem":"你想说\"尽管活动的模式变了,总量却没减少\"(although 让步):","options":["Although the pattern change, the total activity does not fall.","Although the pattern changes, the total activity does not fall.","Despite the pattern changes, the total activity does not fall.","Although the pattern changes, but the total activity does not fall."],"answer_index":1,"explanation_cn":"Although 引导让步,主句前不再加 but;change 随单数 the pattern 用 changes;不用 Despite 直接接句子。✓ Although … changes, … does not fall. 场合:说“尽管…,却…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',9,NULL,'choice','{"stem":"你想说\"被唤醒的人说他们刚才一直在做梦\"(过去完成进行时):","options":["The woken people said they have been dreaming.","The woken people said they had being dreaming.","The woken people said they had been dreaming.","The woken people said they had been dream."],"answer_index":2,"explanation_cn":"过去完成进行时 had + been + 现在分词 dreaming;不用 have、dream 须用 -ing dreaming、been 不写成 being。✓ had been dreaming. 场合:说“(过去某时之前)一直在做…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',10,NULL,'choice','{"stem":"hypothesis 的意思是:","options":["结论","假设,假说","事实","证据"],"answer_index":1,"explanation_cn":"hypothesis = 假设、假说。✓ a plausible hypothesis."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',10,NULL,'choice','{"stem":"disorder 的意思是:","options":["平静","健康","失调,紊乱","秩序"],"answer_index":2,"explanation_cn":"disorder = 失调、紊乱。✓ disorders of mood and personality."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',10,NULL,'choice','{"stem":"\"The body repairs itself ___ we sleep or not.\"(‘无论…与否’)","options":["if only","whether","unless","that"],"answer_index":1,"stem_cn":"无论我们睡不睡,身体都会自我修复。","explanation_cn":"‘无论…与否’用 whether。✓ repairs itself whether we sleep or not. ✗ that / if only / unless。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',10,NULL,'choice','{"stem":"\"___ the pattern changes, the total activity does not fall.\"(‘尽管’,让步连词)","options":["Once","Unless","Because","Although"],"answer_index":3,"stem_cn":"尽管模式变了,总量却没减少。","explanation_cn":"‘尽管’引导让步,用 Although。✓ Although the pattern changes, the total does not fall. ✗ Because / Once / Unless。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',10,NULL,'choice','{"stem":"\"stand in the way\" 的意思是:","options":["让路","站岗","阻碍、成为障碍","排队"],"answer_index":2,"explanation_cn":"stand in the way = 阻碍、成为障碍。✓ two facts stand in its way."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',10,NULL,'choice','{"stem":"\"night after night\" 的意思是:","options":["通宵","一夜又一夜、夜复一夜","半夜","昨晚"],"answer_index":1,"explanation_cn":"night after night = 一夜又一夜、夜复一夜。✓ disturbed night after night."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',10,NULL,'choice','{"stem":"According to the passage, why isn''t sleep simply about resting the body?","options":["The body''s tissues repair themselves and work best when active","The body needs no rest at all","Rest cannot be had by sitting","Sleep tires the body more"],"answer_index":0,"passage":"It is fairly clear that sleep must do something for us, and since we spend so much of our lives asleep, that something is probably important. There has been speculation for thousands of years about what it is for, yet one odd finding keeps the whole question alive: sleep does not seem to be simply a way of giving the body a rest. The kind of rest that loosens the muscles can be had just as well by lying, or even sitting, quietly for a while. The body''s own tissues repair and renew themselves whether we sleep or not, and in fact they work best when they are kept more or less constantly in motion; a certain amount of movement even goes on during sleep, precisely to stop the muscles from growing stiff. If sleep is not there to rest the body, then perhaps it is the brain that needs the rest. This sounds like a plausible hypothesis, but two facts stand in its way. First, the electrical activity of the brain can be traced by fixing small electrodes to the scalp, and the record shows that, although the pattern of that activity changes during sleep, its total amount does not fall. Second — and this is the more interesting point — a psychiatrist some years ago described a strange thing: the ordinary night''s sleep is punctuated by sudden bursts of eye movement, some of them slow and drifting, others quick and jerky. People woken during one of these bursts nearly always said they had been dreaming; woken at other moments, they reported nothing. When one group of volunteers was disturbed, night after night, every time their eyes began to move, while a second group was disturbed just as often but only during quiet, movement-free sleep, the first group soon began to show odd disorders of mood and personality, and the second seemed hardly affected at all. The implication was striking: what mattered was not the loss of sleep itself, but the loss of dreaming.","explanation_cn":"课文说睡眠不只是让身体休息,因为身体组织无论睡不睡都在自我修复,且活动时状态最好。✓ tissues repair, best when active."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',10,NULL,'choice','{"stem":"What did the experiment finally suggest was important?","options":["The time of night","The comfort of the bed","The dreaming, not the loss of sleep itself","The total hours of sleep"],"answer_index":2,"passage":"It is fairly clear that sleep must do something for us, and since we spend so much of our lives asleep, that something is probably important. There has been speculation for thousands of years about what it is for, yet one odd finding keeps the whole question alive: sleep does not seem to be simply a way of giving the body a rest. The kind of rest that loosens the muscles can be had just as well by lying, or even sitting, quietly for a while. The body''s own tissues repair and renew themselves whether we sleep or not, and in fact they work best when they are kept more or less constantly in motion; a certain amount of movement even goes on during sleep, precisely to stop the muscles from growing stiff. If sleep is not there to rest the body, then perhaps it is the brain that needs the rest. This sounds like a plausible hypothesis, but two facts stand in its way. First, the electrical activity of the brain can be traced by fixing small electrodes to the scalp, and the record shows that, although the pattern of that activity changes during sleep, its total amount does not fall. Second — and this is the more interesting point — a psychiatrist some years ago described a strange thing: the ordinary night''s sleep is punctuated by sudden bursts of eye movement, some of them slow and drifting, others quick and jerky. People woken during one of these bursts nearly always said they had been dreaming; woken at other moments, they reported nothing. When one group of volunteers was disturbed, night after night, every time their eyes began to move, while a second group was disturbed just as often but only during quiet, movement-free sleep, the first group soon began to show odd disorders of mood and personality, and the second seemed hardly affected at all. The implication was striking: what mattered was not the loss of sleep itself, but the loss of dreaming.","explanation_cn":"课文说实验最终表明:要紧的不是睡眠本身的丧失,而是做梦的丧失。✓ the dreaming mattered."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',10,NULL,'choice','{"stem":"What is a person usually doing during rapid eye-movement sleep?","options":["Resting the muscles","Talking aloud","Waking up","Dreaming"],"answer_index":3,"audio":"It is fairly clear that sleep must do something for us, and since we spend so much of our lives asleep, that something is probably important. There has been speculation for thousands of years about what it is for, yet one odd finding keeps the whole question alive: sleep does not seem to be simply a way of giving the body a rest. The kind of rest that loosens the muscles can be had just as well by lying, or even sitting, quietly for a while. The body''s own tissues repair and renew themselves whether we sleep or not, and in fact they work best when they are kept more or less constantly in motion; a certain amount of movement even goes on during sleep, precisely to stop the muscles from growing stiff. If sleep is not there to rest the body, then perhaps it is the brain that needs the rest. This sounds like a plausible hypothesis, but two facts stand in its way. First, the electrical activity of the brain can be traced by fixing small electrodes to the scalp, and the record shows that, although the pattern of that activity changes during sleep, its total amount does not fall. Second — and this is the more interesting point — a psychiatrist some years ago described a strange thing: the ordinary night''s sleep is punctuated by sudden bursts of eye movement, some of them slow and drifting, others quick and jerky. People woken during one of these bursts nearly always said they had been dreaming; woken at other moments, they reported nothing. When one group of volunteers was disturbed, night after night, every time their eyes began to move, while a second group was disturbed just as often but only during quiet, movement-free sleep, the first group soon began to show odd disorders of mood and personality, and the second seemed hardly affected at all. The implication was striking: what mattered was not the loss of sleep itself, but the loss of dreaming.","explanation_cn":"录音说人在快速眼动睡眠期间通常是在做梦。✓ dreaming."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l19',10,NULL,'choice','{"stem":"How was the brain''s electrical activity recorded?","options":["By measuring the heartbeat","By fixing small electrodes to the scalp","By timing the breathing","By taking blood samples"],"answer_index":1,"audio":"It is fairly clear that sleep must do something for us, and since we spend so much of our lives asleep, that something is probably important. There has been speculation for thousands of years about what it is for, yet one odd finding keeps the whole question alive: sleep does not seem to be simply a way of giving the body a rest. The kind of rest that loosens the muscles can be had just as well by lying, or even sitting, quietly for a while. The body''s own tissues repair and renew themselves whether we sleep or not, and in fact they work best when they are kept more or less constantly in motion; a certain amount of movement even goes on during sleep, precisely to stop the muscles from growing stiff. If sleep is not there to rest the body, then perhaps it is the brain that needs the rest. This sounds like a plausible hypothesis, but two facts stand in its way. First, the electrical activity of the brain can be traced by fixing small electrodes to the scalp, and the record shows that, although the pattern of that activity changes during sleep, its total amount does not fall. Second — and this is the more interesting point — a psychiatrist some years ago described a strange thing: the ordinary night''s sleep is punctuated by sudden bursts of eye movement, some of them slow and drifting, others quick and jerky. People woken during one of these bursts nearly always said they had been dreaming; woken at other moments, they reported nothing. When one group of volunteers was disturbed, night after night, every time their eyes began to move, while a second group was disturbed just as often but only during quiet, movement-free sleep, the first group soon began to show odd disorders of mood and personality, and the second seemed hardly affected at all. The implication was striking: what mattered was not the loss of sleep itself, but the loss of dreaming.","explanation_cn":"录音说大脑的电活动是通过把小电极贴到头皮上来记录的。✓ electrodes to the scalp."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l20',4,4,20,'Snake Poison','蛇毒','疑问词引导的名词从句作主语(How snakes came to make venom is a mystery)、情态动词 + have done 对过去的推测(can hardly / must / can''t have done)、It is said/believed that …(被动 + that 从句)、though 让步 + whenever、as … as(同级比较)(NCE4 无 KS 页,考点由课文结构自取;IP:源为约翰·克朗普顿《蛇》,内容为‘蛇毒起源·神经毒与血液毒’的生物学事实,已用 100% 原创行文复述,无逐句改写、无人物;题材=蛇毒生物学·无害;美语化 sulfur/mustache;第四册第20课)','蛇究竟怎么会造出毒液,是个真正的谜。经过无数岁月,它们的唾液——一种普普通通、温和的消化液,和我们自己的差不多——不知怎么就变成了一种毒,复杂到至今仍让人无从分析。生存竞争几乎不可能曾迫使它们这样改变,因为成千上万种无毒的蛇,不用一滴毒液,照样能捕到并吞下猎物。对一条蛇来说,毒其实是种奢侈:它让这动物几乎不费吹灰之力就赢得一顿饭——不过咬一口的功夫。可为什么偏偏是蛇?人们会想,一只猫也一样用得上这份礼物;它就能省去许多场同大老鼠的凶猛搏斗。说真的,毒液对几乎任何食肉动物都是助力,尽管每当两个这样的猎手打起来,它也会成为一把双刃剑。然而,在所有脊椎动物里,变幻莫测的大自然偏偏把这件武器交给了蛇——还奇怪地交给了唯一一种蜥蜴——此外谁也没有。蛇毒以两种截然不同的方式发挥它致命的作用。有些蛇,比如眼镜蛇,带的是攻击神经的毒;另一些,比如蝰蛇,带的是攻击血液的毒。这两者彼此不同,不同到不能再不同,各有各的威力。人们常说,神经毒是更古老、更原始的一种,而血液毒是改良配方后更新近的产物。无论这话真假,蛇发展出毒液,根本不是为了对付人,而是为了对付老鼠、耗子之类的小猎物——对这些小小的猎物,毒几乎立刻见效。','{"q":"Listen and answer — What are the two different ways in which snake poison acts?","options":["One acts on the nerves, the other on the blood","One burns, the other freezes","One is real, the other is fake","One is fast, the other is slow to appear"],"answer_index":0}'::jsonb,'{"title":"how 从句作主语 / 情态+have done / It is said that / though·whenever / as…as","intro":"①疑问词从句作主语:How snakes came to make venom is a mystery(全句谓语用 is)。②情态词 + have + 过去分词,对过去推测:can hardly have forced / must have developed。③It is said/believed that …(被动 + that 从句)。④though 让步;whenever‘每当’。⑤as + 形容词/副词 + as(同级比较)。","table":{"headers":["用法","结构","例子"],"rows":[["how 从句作主语","How … + is/was …","How snakes came to make venom is a mystery"],["情态+have done","情态词 + have + 过去分词","can hardly have forced the change"],["It is said that","It is said/believed that …","It is said that the nerve poison is older"],["though / whenever","though + 从句 / whenever + 从句","though it may harm its own kind"],["as … as","as + 形容词/副词 + as","as deadly as the other"]]},"specialRules":[{"rule":"疑问词(how/why/what…)引导的名词从句作句首成分时,后面全句谓语用单数(is);从句内用陈述语序。","mark":"How … is a mystery"},{"rule":"情态词 + have + 过去分词表对过去的推测:can hardly have done(不大可能曾)、must have done(一定曾)、can''t have done(不可能曾)。","mark":"情态词 + have + 过去分词"},{"rule":"美式拼写:sulfur(硫,英式 sulphur)、mustache(胡子,英式 moustache)。本课已按美语写。","mark":"sulfur / mustache"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l20',1,NULL,'How snakes ever came to make venom is a real mystery. Over countless ages their saliva — an ordinary, mild digestive juice much like our own — was somehow turned into a poison so complex that it defies analysis even now.','蛇究竟怎么会造出毒液,是个真正的谜。经过无数岁月,它们的唾液——一种普普通通、温和的消化液,和我们自己的差不多——不知怎么就变成了一种毒,复杂到至今仍让人无从分析。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l20',2,NULL,'Survival can hardly have forced the change upon them, for thousands of harmless snakes still catch and swallow their prey perfectly well without a drop of venom. To a snake, poison is really a luxury: it lets the animal win its dinner with almost no effort — no more than a single bite.','生存竞争几乎不可能曾迫使它们这样改变,因为成千上万种无毒的蛇,不用一滴毒液,照样能捕到并吞下猎物。对一条蛇来说,毒其实是种奢侈:它让这动物几乎不费吹灰之力就赢得一顿饭——不过咬一口的功夫。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l20',3,NULL,'And why snakes alone? A cat, one would think, could use the gift just as much; it would be spared many a fierce struggle with a large rat. In truth venom would be a help to almost any carnivore, though it might prove a two-edged weapon whenever two such hunters fell to fighting.','可为什么偏偏是蛇?人们会想,一只猫也一样用得上这份礼物;它就能省去许多场同大老鼠的凶猛搏斗。说真的,毒液对几乎任何食肉动物都是助力,尽管每当两个这样的猎手打起来,它也会成为一把双刃剑。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l20',4,NULL,'Yet, of all the vertebrates, unpredictable Nature handed this weapon to the snakes — and, oddly, to a single lizard — and to no one else. Snake venom does its deadly work in two quite different ways. Some snakes, among them the cobras, carry a poison that strikes at the nerves; others, such as the vipers, carry one that attacks the blood.','然而,在所有脊椎动物里,变幻莫测的大自然偏偏把这件武器交给了蛇——还奇怪地交给了唯一一种蜥蜴——此外谁也没有。蛇毒以两种截然不同的方式发挥它致命的作用。有些蛇,比如眼镜蛇,带的是攻击神经的毒;另一些,比如蝰蛇,带的是攻击血液的毒。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l20',5,NULL,'The two are as unlike each other as two poisons can be, and each has its own potency. It is often said that the nerve poison is the older, more primitive kind, and the blood poison a newer product of an improved recipe. Whatever the truth of that, snakes did not develop their venom to use against people at all, but against small prey such as rats and mice — and on these little victims the poison acts almost at once.','这两者彼此不同,不同到不能再不同,各有各的威力。人们常说,神经毒是更古老、更原始的一种,而血液毒是改良配方后更新近的产物。无论这话真假,蛇发展出毒液,根本不是为了对付人,而是为了对付老鼠、耗子之类的小猎物——对这些小小的猎物,毒几乎立刻见效。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
